BEGIN;
DO $$
DECLARE creator UUID; reviewer UUID; approver UUID; accountant UUID; member_a UUID; member_b UUID; org UUID; source_period UUID; retained UUID; payable UUID; wallet_a UUID; wallet_b UUID; distribution UUID; result JSONB; replay JSONB; row dividend_distributions;
BEGIN
 distribution:=calculate_dividend_entitlement_snapshot(org,creator,source_period,'fy2027_surplus','NGN',1001,100,DATE '2027-12-31',DATE '2028-02-01','{}',jsonb_build_array(jsonb_build_object('member_id',member_a,'paid_units',1),jsonb_build_object('member_id',member_b,'paid_units',2)),'div04-calc',clock_timestamp());
 PERFORM review_dividend_distribution(org,reviewer,distribution,'Distribution independently reviewed',clock_timestamp()); PERFORM approve_dividend_distribution(org,approver,distribution,clock_timestamp()); PERFORM recognize_dividend_payable(org,accountant,distribution,retained,payable,DATE '2028-02-01','div04-payable','00000000-0000-4000-8000-000000006401',clock_timestamp());
 result:=pay_dividend_distribution(org,accountant,distribution,DATE '2028-02-01','00000000-0000-4000-8000-000000006402',clock_timestamp()); replay:=pay_dividend_distribution(org,accountant,distribution,DATE '2028-02-01','00000000-0000-4000-8000-000000006402',clock_timestamp()); SELECT * INTO row FROM dividend_distributions WHERE id=distribution;
 IF row.state<>'paid' OR jsonb_array_length(row.payment_journal_ids)<>2 OR replay->>'state'<>'paid' OR (SELECT count(*) FROM journal_entries WHERE source_domain='dividend.payment' AND source_record_id IN(SELECT id::TEXT FROM dividend_entitlements WHERE distribution_id=distribution))<>2 OR (SELECT sum(CASE WHEN line.account_id=wallet_a OR line.account_id=wallet_b THEN line.amount_minor ELSE 0 END) FROM journal_lines line JOIN journal_entries entry ON entry.id=line.journal_entry_id WHERE entry.source_domain='dividend.payment')<>1000 THEN RAISE EXCEPTION 'DIV04 payment servicing invalid: row %, replay %, journals %, wallet total %',row,replay,(SELECT count(*) FROM journal_entries WHERE source_domain='dividend.payment'),(SELECT sum(CASE WHEN line.account_id=wallet_a OR line.account_id=wallet_b THEN line.amount_minor ELSE 0 END) FROM journal_lines line JOIN journal_entries entry ON entry.id=line.journal_entry_id WHERE entry.source_domain='dividend.payment'); END IF;
 BEGIN PERFORM pay_dividend_distribution(org,member_a,distribution,DATE '2028-02-01','00000000-0000-4000-8000-000000006403',clock_timestamp()); RAISE EXCEPTION 'unauthorized dividend payment accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unauthorized dividend payment accepted' OR SQLERRM NOT LIKE '%DIVIDEND_PAYMENT_PERMISSION_DENIED%' THEN RAISE; END IF; END;
 IF has_function_privilege('authenticated','pay_dividend_distribution(uuid,uuid,uuid,date,uuid,timestamp with time zone)','EXECUTE') THEN RAISE EXCEPTION 'authenticated clients can bypass dividend payment boundary'; END IF;
END $$;
SELECT 'dividend payment servicing schema tests passed' AS result;
ROLLBACK;
